<template><section v-if="tiers.length" class="learning-pay"><h3>Learning compensation</h3><p>Staff may provide both counseling and learning services. Select their service categories above; assign each pay level separately.</p><p v-if="counseling">Counseling: category {{counseling.category}} · {{counseling.bypass?'existing rate override':`level ${counseling.level}`}}. Use the counseling compensation controls below to change it.</p><label>Learning level<select v-model="tierId"><option value="">Not assigned</option><option v-for="t in tiers" :key="t.id" :value="t.id">{{t.id}} — {{t.name}}</option></select></label><p>{{tier?.description}}</p><table v-if="tier"><thead><tr><th>Format</th><th>Employee pay / hour</th><th>Client fee / hour</th></tr></thead><tbody><tr v-for="format in ['virtual','in-person']" :key="format"><th>{{format==='virtual'?'Virtual':'In person'}}</th><td>{{money(tier.pay[format])}}</td><td>{{money(tier.fees[format])}}</td></tr></tbody></table><label>Pay effective date<input v-model="effectiveStart" type="date" required/></label><p>Saving sets this learning tier and its two payroll rates. Record learning hours with “TUTORING VIRTUAL” or “TUTORING IN PERSON.” Counseling rates stay intact. Client fee defaults apply to new quotes immediately; existing purchases retain their price.</p><button type="button" :disabled="saving||!tierId||!effectiveStart" @click="save">{{saving?'Saving…':'Save learning level & pay'}}</button><p v-if="message" role="status">{{message}}</p><p v-if="error" role="alert">{{error}}</p></section></template>
<script setup>
import {computed,ref,watch} from 'vue';import api from '../../services/api';
const props=defineProps({agencyId:[Number,String],userId:[Number,String]});const tiers=ref([]),tierId=ref(''),counseling=ref(null),saving=ref(false),error=ref(''),message=ref(''),effectiveStart=ref(new Date().toLocaleDateString('en-CA'));const tier=computed(()=>tiers.value.find(t=>t.id===tierId.value));const money=n=>n==null?'Not set':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);const endpoint=computed(()=>`/tenant-booking/agencies/${props.agencyId}/providers/${props.userId}/learning-compensation`);let version=0;
function apply(d){tiers.value=d.tiers;tierId.value=d.tierId;counseling.value=d.counseling;}
watch(endpoint,async()=>{const request=++version;tiers.value=[];if(!props.agencyId||!props.userId)return;try{const {data}=await api.get(endpoint.value);if(request===version)apply(data);}catch(e){if(request===version)error.value=e.response?.data?.error?.message||'Could not load learning compensation.';}},{immediate:true});
async function save(){saving.value=true;message.value='';error.value='';try{const {data}=await api.put(endpoint.value,{tierId:tierId.value,effectiveStart:effectiveStart.value});apply(data);message.value='Learning pay saved. Counseling compensation was preserved.';}catch(e){error.value=e.response?.data?.error?.message||'Could not save learning compensation.';}finally{saving.value=false;}}
</script><style scoped>.learning-pay{border:1px solid #cbdde3;padding:20px;border-radius:10px;margin-bottom:24px}label{display:grid;gap:6px;margin:14px 0}select,input,button{font:inherit;padding:9px}th,td{text-align:left;padding:10px}p{line-height:1.6}</style>
